local MAX_SQUARES = 200

local function linkFrom(obj)
    local spr = obj and obj.getSprite and obj:getSprite()
    local name = spr and spr:getName()
    local key = name and GROUP[name]
    if not key then return end
    local state = obj:isActivated()
    local start = obj:getSquare()
    if not start then return end
    local cell = getCell()
    local z = start:getZ()
    local seen = { [start:getX() .. "," .. start:getY()] = true }
    local queue, head, count = { start }, 1, 0
    local steps = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }
    while head <= #queue and count < MAX_SQUARES do
        local sq = queue[head]
        head = head + 1
        local found = false
        local objs = sq:getObjects()
        for i = 0, objs:size() - 1 do
            local o = objs:get(i)
            local s = o and o:getSprite()
            local n = s and s:getName()
            if n and GROUP[n] == key and instanceof(o, "IsoLightSwitch") then
                found = true
                if o ~= obj and o:isActivated() ~= state then o:toggle() end
            end
        end
        if found then
            count = count + 1
            for k = 1, #steps do
                local x, y = sq:getX() + steps[k][1], sq:getY() + steps[k][2]
                local id = x .. "," .. y
                if not seen[id] then
                    seen[id] = true
                    local nsq = cell:getGridSquare(x, y, z)
                    if nsq then queue[#queue + 1] = nsq end
                end
            end
        end
    end
end

